"""Native group normalization as a single fused Triton kernel.

One program per (group, batch) pair.  Each program

1. walks its whole group (CG channels x HW elements) accumulating sum and
   sum-of-squares in fp32 with a chunked per-channel loop,
2. derives ``mean`` / ``rstd`` and stores them,
3. re-walks the same range applying ``y = x * a + b`` with per-channel
   ``a = rstd * w`` and ``b = bias - mean * rstd * w``.

Measured on this target, the whole operator is host-overhead bound (the
reference operator itself measures ~30us/call for every shape), so the wrapper
launch one kernel, does one output allocation plus one fused mean/rstd
allocation, and re-uses the compiled kernel's own launch entry once Triton has
built it for the current specialization.
"""
import torch
import triton
import triton.language as tl

@triton.jit
def _gn_kernel(X, OUT, MEAN, RSTD, W, B, eps, HW: tl.constexpr, CG: tl.constexpr, G: tl.constexpr, NS: tl.constexpr, CS: tl.constexpr, SS: tl.constexpr, COUNT: tl.constexpr, BLOCK: tl.constexpr, HAS_WEIGHT: tl.constexpr, HAS_BIAS: tl.constexpr, EVEN: tl.constexpr):
    g = tl.program_id(0)
    n = tl.program_id(1)
    c0 = g * CG
    xb = X + n * NS + c0 * CS
    idx = tl.arange(0, BLOCK)
    accs = tl.zeros([BLOCK], dtype=tl.float32)
    accq = tl.zeros([BLOCK], dtype=tl.float32)
    for ci in range(0, CG):
        co = ci * CS
        for start in range(0, HW, BLOCK):
            hi = start + idx
            if EVEN:
                xf = tl.load(xb + co + hi * SS).to(tl.float32)
            else:
                msk = hi < HW
                xf = tl.load(xb + co + hi * SS, mask=msk, other=0.0).to(tl.float32)
            accs += xf
            accq += xf * xf
    inv = 1.0 / COUNT
    mean = tl.sum(accs, 0) * inv
    var = tl.sum(accq, 0) * inv - mean * mean
    rstd = 1.0 / tl.sqrt(var + eps)
    midx = n * G + g
    tl.store(MEAN + midx, mean.to(MEAN.dtype.element_ty))
    tl.store(RSTD + midx, rstd.to(RSTD.dtype.element_ty))
    cb = midx * COUNT
    for ci in range(0, CG):
        co = ci * CS
        oo = ci * HW
        if HAS_WEIGHT:
            a = rstd * tl.load(W + c0 + ci).to(tl.float32)
        else:
            a = rstd
        if HAS_BIAS:
            b2 = tl.load(B + c0 + ci).to(tl.float32) - mean * a
        else:
            b2 = -mean * a
        for start in range(0, HW, BLOCK):
            hi = start + idx
            if EVEN:
                xf = tl.load(xb + co + hi * SS).to(tl.float32)
                tl.store(OUT + cb + oo + hi, (xf * a + b2).to(OUT.dtype.element_ty))
            else:
                msk = hi < HW
                xf = tl.load(xb + co + hi * SS, mask=msk, other=0.0).to(tl.float32)
                tl.store(OUT + cb + oo + hi, (xf * a + b2).to(OUT.dtype.element_ty), mask=msk)
_BLOCK_CACHE = {}
_CK_CACHE = {}
_STREAM_FN = None

def _as_int(value):
    if isinstance(value, int):
        return value
    try:
        return int(value)
    except Exception:
        return int(value.value)

def _stream_slow():
    return _as_int(torch.npu.current_stream()._as_parameter_)

def _stream_candidates():
    cands = []
    try:
        import torch_npu
        mod = getattr(torch_npu, '_C', None)
        fn = getattr(mod, '_npu_getCurrentRawStreamNoWait', None)
        if fn is not None:
            cands.append(lambda fn=fn: _as_int(fn(0)))
        fn = getattr(mod, '_npu_getCurrentRawStream', None)
        if fn is not None:
            cands.append(lambda fn=fn: _as_int(fn(0)))
        fn = getattr(mod, '_npu_getCurrentStream', None)
        if fn is not None:
            cands.append(lambda fn=fn: _as_int(fn(0)._as_parameter_))
    except Exception:
        pass
    return cands

def _resolve_stream():
    """Cache a cheap callable that returns this device's current stream handle.

    Only a candidate that reproduces the full ``current_stream()`` handle is
    accepted, so the fast path can never pick a different stream than the one
    the caller is using.
    """
    global _STREAM_FN
    if _STREAM_FN is not None:
        return
    try:
        good = _stream_slow()
    except Exception:
        return
    for cand in _stream_candidates():
        try:
            if cand() == good:
                _STREAM_FN = cand
                return
        except Exception:
            continue

def _stream_ptr():
    fn = _STREAM_FN
    if fn is not None:
        try:
            return fn()
        except Exception:
            pass
    return _stream_slow()

def _pick_block(hw):
    blk = _BLOCK_CACHE.get(hw)
    if blk is None:
        blk = 64
        while blk < hw and blk < 4096:
            blk <<= 1
        _BLOCK_CACHE[hw] = blk
    return blk

def _cache_keys():
    keys = set()
    caches = getattr(_gn_kernel, 'device_caches', None)
    if not caches:
        return keys
    for entry in caches.values():
        cache = entry[0] if isinstance(entry, (tuple, list)) else entry
        try:
            keys.update(cache.keys())
        except Exception:
            pass
    return keys

def _find_new(before):
    caches = getattr(_gn_kernel, 'device_caches', None)
    if not caches:
        return None
    for entry in caches.values():
        cache = entry[0] if isinstance(entry, (tuple, list)) else entry
        try:
            for key, value in cache.items():
                if key not in before:
                    return value
        except Exception:
            pass
    return None

def _legacy_run(input, weight, bias, N, C, HxW, group, eps):
    x = input
    dt = x.dtype
    device = x.device
    out = torch.empty(x.shape, dtype=dt, device=device)
    mean = torch.empty((N, group), dtype=dt, device=device)
    rstd = torch.empty((N, group), dtype=dt, device=device)
    dim = x.dim()
    st = x.stride()
    ns = st[0]
    cs = st[1]
    if dim > 2:
        ss = st[dim - 1]
        if dim > 3:
            acc = 1
            shape = x.shape
            for d in range(dim - 1, 2, -1):
                if st[d] != ss * acc:
                    x = _strict_contiguous(x)
                    st = x.stride()
                    ns = st[0]
                    cs = st[1]
                    ss = st[dim - 1]
                    break
                acc *= shape[d]
    else:
        ss = 1
    hw = HxW
    cg = C // group
    count = cg * hw
    block = _pick_block(hw)
    even = hw % block == 0
    has_weight = weight is not None
    has_bias = bias is not None
    wsrc = x if weight is None else weight
    bsrc = x if bias is None else bias
    xp = x.data_ptr()
    op = out.data_ptr()
    mp = mean.data_ptr()
    rp = rstd.data_ptr()
    wp = wsrc.data_ptr()
    bp = bsrc.data_ptr()
    key = (dt, wsrc.dtype, bsrc.dtype, has_weight, has_bias, xp & 15, op & 15, mp & 15, rp & 15, wp & 15, bp & 15, hw, cg, group, ns, cs, ss, count, eps, block, even)
    ent = _CK_CACHE.get(key)
    if ent is not None and ent is not False:
        ent[0](group, N, 1, _stream_ptr(), ent[1], ent[2], None, None, None, xp, op, mp, rp, wp, bp, eps, hw, cg, group, ns, cs, ss, count, block, int(has_weight), int(has_bias), int(even))
        return (out, mean, rstd)
    if ent is False:
        _gn_kernel[group, N](x, out, mean, rstd, wsrc, bsrc, eps, HW=hw, CG=cg, G=group, NS=ns, CS=cs, SS=ss, COUNT=count, BLOCK=block, HAS_WEIGHT=has_weight, HAS_BIAS=has_bias, EVEN=even)
        return (out, mean, rstd)
    before = _cache_keys()
    try:
        _gn_kernel[group, N](x, out, mean, rstd, wsrc, bsrc, eps, HW=hw, CG=cg, G=group, NS=ns, CS=cs, SS=ss, COUNT=count, BLOCK=block, HAS_WEIGHT=has_weight, HAS_BIAS=has_bias, EVEN=even)
        ck = _gn_kernel.warmup(x, out, mean, rstd, wsrc, bsrc, eps, HW=hw, CG=cg, G=group, NS=ns, CS=cs, SS=ss, COUNT=count, BLOCK=block, HAS_WEIGHT=has_weight, HAS_BIAS=has_bias, EVEN=even, grid=(group, N))
        if ck is not None and hasattr(ck, 'run') and (not getattr(ck.run, 'compile_only', False)) and (not getattr(ck.run, 'enable_msprof_register_tensor', False)) and (not getattr(ck.run.metadata, 'debug_enabled', False)) and (not getattr(ck.run.metadata, 'debug', False)):
            _CK_CACHE[key] = (ck.run.launch, ck.function, ck.packed_metadata)
            _resolve_stream()
        else:
            _CK_CACHE[key] = False
    except Exception:
        _CK_CACHE[key] = False
    return (out, mean, rstd)
native_group_norm = _legacy_run
_HOST_PLANS = {}

def run(input, weight, bias, N, C, HxW, group, eps):
    x = input
    if weight is not None and (not weight.is_contiguous()):
        weight = _strict_contiguous(weight)
    if bias is not None and (not bias.is_contiguous()):
        bias = _strict_contiguous(bias)
    if not x.is_contiguous():
        return _legacy_run(x, weight, bias, N, C, HxW, group, eps)
    xp = x.data_ptr()
    wp = xp if weight is None else weight.data_ptr()
    bp = xp if bias is None else bias.data_ptr()
    if (xp | wp | bp) & 15:
        return _legacy_run(x, weight, bias, N, C, HxW, group, eps)
    has_weight, has_bias = (weight is not None, bias is not None)
    key = (x.dtype, x.device.index, tuple(x.shape), N, C, HxW, group, eps, has_weight, has_bias, None if weight is None else weight.dtype, None if bias is None else bias.dtype)
    plan = _HOST_PLANS.get(key)
    if plan is False:
        return _legacy_run(x, weight, bias, N, C, HxW, group, eps)
    out = x.new_empty(x.shape)
    mean = x.new_empty((N, group))
    rstd = x.new_empty((N, group))
    if plan is None:
        block = _pick_block(HxW)
        cg = C // group
        even = HxW % block == 0
        try:
            ck = _gn_kernel.warmup(x, out, mean, rstd, x if weight is None else weight, x if bias is None else bias, eps, HW=HxW, CG=cg, G=group, NS=C * HxW, CS=HxW, SS=1, COUNT=cg * HxW, BLOCK=block, HAS_WEIGHT=has_weight, HAS_BIAS=has_bias, EVEN=even, grid=(group, N))
            launcher = ck.run
            if getattr(launcher, 'compile_only', False) or getattr(launcher, 'enable_msprof_register_tensor', False) or getattr(launcher.metadata, 'debug_enabled', False) or getattr(launcher.metadata, 'debug', False):
                raise RuntimeError('use registered profiling launcher')
            tail = (eps, HxW, cg, group, C * HxW, HxW, 1, cg * HxW, block, int(has_weight), int(has_bias), int(even))
            plan = (launcher.launch, ck.function, ck.packed_metadata, tail)
            _HOST_PLANS[key] = plan
            _resolve_stream()
        except Exception:
            _HOST_PLANS[key] = False
            return _legacy_run(x, weight, bias, N, C, HxW, group, eps)
    plan[0](group, N, 1, _stream_ptr(), plan[1], plan[2], None, None, None, xp, out.data_ptr(), mean.data_ptr(), rstd.data_ptr(), wp, bp, *plan[3])
    return (out, mean, rstd)
native_group_norm = run

"""候选内嵌的Triton存储操作：复制、连续化、填充、转换均执行Triton核。"""
import torch
import triton
import triton.language as tl

@triton.jit
def _strict_copy_kernel(X,Y,N:tl.constexpr,SHAPE:tl.constexpr,XS:tl.constexpr,YS:tl.constexpr,BLOCK:tl.constexpr):
    i=tl.program_id(0)*BLOCK+tl.arange(0,BLOCK)
    remain=i;xp=tl.full((BLOCK,),0,tl.int64);yp=tl.full((BLOCK,),0,tl.int64)
    for d in tl.static_range(len(SHAPE)-1,-1,-1):
        coord=remain%SHAPE[d];remain=remain//SHAPE[d]
        xp+=coord*XS[d];yp+=coord*YS[d]
    value=tl.load(X+xp,i<N,other=0)
    tl.store(Y+yp,value,i<N)

@triton.jit
def _strict_fill_kernel(Y,N:tl.constexpr,VALUE:tl.constexpr,BLOCK:tl.constexpr):
    i=tl.program_id(0)*BLOCK+tl.arange(0,BLOCK)
    tl.store(Y+i,VALUE,i<N)

@triton.jit
def _strict_random_kernel(Y,N:tl.constexpr,SEED,OFFSET,BLOCK:tl.constexpr):
    i=tl.program_id(0)*BLOCK+tl.arange(0,BLOCK)
    # 备用随机采样路径；全部随机数计算在Triton内，生成器仅在宿主管理状态。
    value=tl.rand(SEED,(i.to(tl.uint64)+OFFSET).to(tl.uint32))
    tl.store(Y+i,value,i<N)

def _strict_empty_like(x,*,dtype=None,**kwargs):
    return torch.empty(tuple(x.shape),device=x.device,dtype=x.dtype if dtype is None else dtype)

def _strict_copy_into(dst,src):
    if tuple(dst.shape)!=tuple(src.shape):raise ValueError('strict copy requires equal shapes')
    if dst.numel():
        _strict_copy_kernel[(triton.cdiv(dst.numel(),1024),)](src,dst,dst.numel(),tuple(dst.shape),tuple(src.stride()),tuple(dst.stride()),1024)
    return dst

def _strict_clone(x,**kwargs):
    return _strict_copy_into(_strict_empty_like(x),x)

def _strict_contiguous(x,*args,**kwargs):
    return x if x.is_contiguous() else _strict_clone(x)

def _strict_cast(x,dtype):
    if dtype==x.dtype:return x
    return _strict_copy_into(_strict_empty_like(x,dtype=dtype),x)

def _strict_reshape(x,*shape):
    # view只操作元数据，输入连续化由上面的Triton复制完成。
    return _strict_contiguous(x).view(*shape)

def _strict_flatten(x,start_dim=0,end_dim=-1):
    rank=x.ndim;first=start_dim%rank;last=end_dim%rank
    size=1
    for n in x.shape[first:last+1]:size*=n
    shape=tuple(x.shape[:first])+(size,)+tuple(x.shape[last+1:])
    return _strict_contiguous(x).view(shape)

def _strict_full(shape,value,**kwargs):
    if isinstance(shape,int):shape=(shape,)
    out=torch.empty(shape,**kwargs)
    if out.numel():_strict_fill_kernel[(triton.cdiv(out.numel(),1024),)](out,out.numel(),value,1024)
    return out

def _strict_zeros(*shape,**kwargs):
    shape=shape[0] if len(shape)==1 else shape
    return _strict_full(shape,0,**kwargs)

def _strict_ones(*shape,**kwargs):
    shape=shape[0] if len(shape)==1 else shape
    return _strict_full(shape,1,**kwargs)

def _strict_rand(*shape,**kwargs):
    shape=shape[0] if len(shape)==1 else shape
    generator=kwargs.pop('generator',None)
    out=torch.empty(shape,**kwargs)
    if out.numel():
        if generator is None:
            import torch_npu
            generator=torch.npu.default_generators[out.device.index or 0]
        seed=generator.initial_seed();offset=generator.get_offset()
        advance=triton.cdiv(out.numel(),4)*4
        if offset+advance>=2**32:raise RuntimeError('备用随机路径超过32位计数范围，明确拒绝而非静默重复')
        generator.set_offset(offset+advance)
        _strict_random_kernel[(triton.cdiv(out.numel(),256),)](out,out.numel(),seed,offset,256)
    return out
